import { money, hex, safeStoreUrl, snapshotDate, matchColors, cameraKit, buildShoppingSummary } from './sourcing-model.js';
let evidencePromise, generation = 0;
const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const link = (url,label,cls='') => safeStoreUrl(url) ? `<a class="${cls}" href="${esc(safeStoreUrl(url))}" target="_blank" rel="noopener noreferrer">${esc(label)} <span aria-hidden="true">↗</span></a>` : `<span>${esc(label)} · link unavailable</span>`;
function filamentCard(match,index,evidence) {
 const p=match.primary;
 if(!p)return `<article class="source-filament"><span class="source-kicker">COLOR ${String(index+1).padStart(2,'0')}</span><h4>${match.target}</h4><p>No priced, 1 kg standard ASA match in the recorded offers. Check a manufacturer directly; this color is excluded from the estimate.</p></article>`;
 return `<article class="source-filament"><div class="source-color-top"><span class="source-pair"><i style="--chip:${match.target}" title="Design ${match.target}"></i><i style="--chip:${hex(p.manufacturer_hex)}" title="Manufacturer ${hex(p.manufacturer_hex)}"></i></span><span class="source-kicker">COLOR ${String(index+1).padStart(2,'0')}</span><span class="source-match">${hex(p.manufacturer_hex)===match.target?'Same published HEX':'Approximate match'}</span></div><h4>${esc(p.color)}</h4><p class="source-brand">${esc(p.brand)} · ASA · 1 kg</p><p class="source-color-code">Design ${match.target} → swatch ${hex(p.manufacturer_hex)}</p><div class="source-buy"><strong>${money(p.price_usd)}</strong>${link(p.url,'View direct store','source-link')}</div><p class="source-stock">Recorded offer · ${esc(snapshotDate(p,evidence))} UTC.<br>Confirm stock, color and final price at the store.</p><details class="source-compare"><summary>Compare ${match.alternatives.length} manufacturers</summary><ul>${match.alternatives.map(({brand,offer:v})=>`<li><strong>${esc(brand)}</strong>${v?`<span>${esc(v.color)} · ${esc(v.material)} · 1 kg · ${money(v.price_usd)}<br><small>${v.manufacturer_hex?'Color-family alternative; shade varies.':'Published HEX not verified.'} Snapshot ${esc(snapshotDate(v,evidence))}; stock may have changed.</small></span>${link(v.url,'Store')}`:'<span class="source-muted">No purchasable color-family alternative recorded in this snapshot.</span>'}</li>`).join('')}</ul></details></article>`;
}
function cameraCard(camera,evidence) {
 const {base,lens,total}=cameraKit(camera);
 const notes=camera.id.includes('birdfy')?'Built-in rechargeable battery: remove the camera before charging. Its published 230 mm height includes the antenna; the modeled body contour is approximate. AI identification may require a paid plan.':'Remove the camera before opening its bottom battery compartment. The official close-up lens is required; lens clearance and focus still need a real-device trial.';
 return `<article class="source-camera is-selected"><div class="source-camera-select"><span class="source-kicker">DESIGN TARGET${lens?' · CLOSE-UP LENS REQUIRED':''}</span><h4>${esc(camera.name)}</h4></div><p>${notes}</p><strong class="source-camera-price">${money(total)} <small>${lens?'camera + required lens':'camera kit'} × 1 · snapshot</small></strong><p class="source-muted">${camera.hub_required?'A separate hub is required.':'No separate hub required.'} Printed fit, retention and focus are not physically validated.</p><div class="source-retail">${(camera.prices||[]).filter(p=>Number.isFinite(p.usd)&&!p.seller.includes('extra battery')).map(p=>link(p.url,`${p.seller} · ${money(p.usd)} · ${p.checked_date_utc||evidence.camera_evidence.checked_date_utc}`)).join('')}${lens?link(lens.url,`Required close-up lens · ${money(lens.usd)} · ${lens.checked_date_utc||evidence.camera_evidence.checked_date_utc}`):''}${(camera.prices||[]).filter(p=>p.usd===null&&p.url).map(p=>link(p.url,`${p.seller} · price not verified`)).join('')}</div></article>`;
}
export function clearSourcing(){generation++;const panel=document.getElementById('sourcing-panel');if(panel){panel.hidden=true;panel.replaceChildren();}}
export async function renderSourcing(design){
 const token=++generation;let panel=document.getElementById('sourcing-panel');
 if(!panel){panel=document.createElement('section');panel.id='sourcing-panel';panel.className='sourcing-panel';panel.setAttribute('aria-labelledby','sourcing-title');const anchor=document.getElementById('print-planning');if(!anchor)return;anchor.after(panel);}
 panel.hidden=false;panel.innerHTML='<p class="source-muted" role="status">Finding this build’s materials…</p>';
 if(!document.querySelector('link[data-nestforge-sourcing]')){const css=document.createElement('link');css.rel='stylesheet';css.href=new URL('./sourcing.css',import.meta.url).href;css.dataset.nestforgeSourcing='';document.head.append(css);}
 try{
  evidencePromise ||= fetch(new URL('./sourcing-data.json',import.meta.url)).then(r=>{if(!r.ok)throw Error('Unavailable');return r.json();}).catch(err=>{evidencePromise=null;throw err;});
  const evidence=await evidencePromise;if(token!==generation)return;
  const matches=matchColors(design,evidence);
  const camera=design.camera_system?evidence.camera_evidence.cameras.find(c=>c.id===design.camera_default):null;
  const summary=buildShoppingSummary(matches,camera,Boolean(design.camera_system));
  const carrier=design.parts[design.camera_part_index], hardware=design.mounting?.hardware;
  const hardwareText=Array.isArray(hardware)?hardware.map(x=>typeof x==='string'?x:JSON.stringify(x)).join('; '):typeof hardware==='string'?hardware:'';
  const bottle=(design.extra_hardware||[]).find(item=>item.type==='recycled-bottle');
  panel.innerHTML=`<div class="source-heading"><div><span class="eyebrow">THE MAKER’S SHOPPING LIST</span><h2 id="sourcing-title">Make ${esc(design.name)} yours.</h2><p>Outdoor ASA options${design.camera_system?' and this prototype’s target camera':'. No camera, app or subscription required'}.</p></div><div id="sourcing-total" class="source-total" aria-live="polite"><span>${summary.complete?'FULL-SPOOL SHOPPING ESTIMATE':'INCOMPLETE SHOPPING ESTIMATE'}</span><strong>${summary.complete?money(summary.total):'Check missing prices'}</strong><small>${summary.spools.length} × 1 kg ASA${camera?' + camera kit × 1':''}<br>Not the cost of filament consumed by one feeder.</small></div></div>
  <p class="source-date">Dated US store snapshots, not live inventory. Each offer shows its own check date. Shipping, tax, mounting hardware and paid camera plans are excluded. Reuse filament you already own when appropriate.</p>
  ${design.camera_system?`<div class="source-section-title"><h3>The camera for this prototype</h3><span>OPTIONAL COLLECTION · PHYSICAL FIT UNTESTED</span></div>${camera?`<div class="source-camera-grid">${cameraCard(camera,evidence)}</div><div class="source-choice"><div><span class="source-kicker">SERVICE & STORAGE</span><h4>${esc(camera.name)}</h4><p>${esc(design.camera_service||camera.service)}</p><p class="source-muted">${esc(camera.storage)}</p></div><div class="source-adapter"><strong>${esc(carrier?.name||'Integrated camera carrier')}</strong><p>Retention geometry belongs to this printed part. It is intended for ${esc(camera.name)} only; a CAD clearance check is not evidence of a tested physical fit.</p><small>Verify the feeding surface is visible and sharply focused before final mounting.</small></div></div>`:'<p class="source-muted">No matching camera offer. The total is incomplete; check this design’s camera metadata before buying.</p>'}`:''}
  ${hardwareText||bottle?`<div class="source-section-title"><h3>Installation & reused hardware</h3><span>NOT INCLUDED IN PRINT FILES</span></div>${hardwareText?`<p>${esc(hardwareText)}</p>`:''}${bottle?'<p><strong>Recycled bottle:</strong> measure the neck against the assembly notes before printing. This is not a universal bottle thread. The viewer’s bottle is illustrative.</p>':''}`:''}
  <div class="source-section-title"><h3>Your outdoor ASA palette</h3><span>${matches.length} DESIGN COLORS</span></div><p class="source-explainer">Left: design color. Right: manufacturer’s published swatch. These are approximate color matches, not equivalent print profiles. Screens and batches vary. Print a small swatch and fit coupon first.${design.material!=='ASA'?' The supplied original plates use PETG; choosing ASA requires changing the filament profile and re-slicing, not simply loading a different spool.':''}</p><div class="source-filament-grid">${matches.map((m,i)=>filamentCard(m,i,evidence)).join('')}</div><p class="source-footnote">This estimate buys one full 1 kg spool per distinct recommended product (${summary.spools.length} total). It is not a per-feeder manufacturing quote. Two design colors may map to the same spool and lose contrast. Compare-store links are alternatives, not additional purchases. No reinforced or lightweight material is silently substituted. Follow the manufacturer’s ASA enclosure, ventilation and drying guidance.</p>
  ${camera?`<details class="source-guide"><summary>Focus, camera service & outdoor checks</summary><div><p><strong>Bench-test focus before installation.</strong> ${cameraKit(camera).lens?'Use the official close-up lens.':'Use the intended feeder camera.'} A numeric minimum focus distance was not found in the checked specifications. Confirm a clear image of the actual feeding surface.</p><p><strong>Keep sensors open.</strong> Lens, PIR, IR emitters and light sensor must remain uncovered. The preview is illustrative; no field of view, battery runtime or weather performance is promised.</p><p><strong>Remove for service.</strong> ${esc(design.camera_service||camera.service)} Keep ports dry, respect operating and charging limits, and reinstall weather covers.</p><p>${link(camera.sources?.[0]?.url,`${camera.name} specifications`)}</p></div></details>`:''}`;
 }catch(error){if(token!==generation)return;panel.innerHTML='<p role="status">The sourcing list could not load. Select this design again to retry. Print downloads remain available above.</p>';}
}
